python -c 'import csv, numpy as np, spglib; from pymatgen.core import Structure; rows=list(csv.DictReader(open("nlo_pool.csv"))); print("Parsed",len(rows),"structures"); selected=list(range(1,20))+list(range(31,37))+list(range(40,46))+list(range(94,100));
for k in selected:
 r=rows[k-1]; s=Structure.from_str(r["poscar"],fmt="poscar"); d=spglib.get_symmetry_dataset((s.lattice.matrix,s.frac_coords,s.atomic_numbers),symprec=0.01); tensors={}; cn={}
 for i,site in enumerate(s):
  e=site.specie.symbol
  if e not in {"Ga","Zn","B","Mg"}: continue
  cutoff={"Ga":2.95,"Zn":2.95,"B":2.2,"Mg":3.1}[e]; nb=[n for n in s.get_neighbors(site,cutoff) if n.specie.symbol in {"S","Se"}]; cn.setdefault(e,[]).append(len(nb)); vs=np.array([(n.coords-site.coords)/n.nn_distance for n in nb]); tensors[e]=tensors.get(e,np.zeros((3,3)))+vs.T@vs
 print(r["candidate_id"],r["formula"],d.international,"V",round(s.volume,2),"CN",{e:sorted(set(v)) for e,v in cn.items()},"Q",{e:np.linalg.eigvalsh(t/np.trace(t)).round(3).tolist() for e,t in tensors.items()})'

